body.dataFilter:
const labels=['初步沟通','需求确认','方案报价','商务谈判','赢单','输单'];
const m={prospecting:0,qualification:1,proposal:2,negotiation:3,closed_won:4,closed_lost:5};
const c=[0,0,0,0,0,0]; (data.rows||[]).forEach(r=>{const i=m[r.stage]; if(i!=null) c[i]++;});
config.xAxis={type:'category',data:labels}; config.yAxis={type:'value'};
config.series=[{type:'bar',name:'数量',data:c,itemStyle:{color:'#0d6efd'}}]; return config;

const sum={}; (data.rows||[]).forEach(r=>{const k=r.owner||'未指派'; sum[k]=(sum[k]||0)+(+r.amount||0);});
const ents=Object.entries(sum).sort((a,b)=>b[1]-a[1]).slice(0,10);
config.xAxis={type:'category',data:ents.map(e=>e[0])}; config.yAxis={type:'value'};
config.series=[{type:'bar',name:'成交金额',data:ents.map(e=>e[1]),itemStyle:{color:'#198754'}}]; return config;

const labels={draft:'草稿',in_approval:'审批中',active:'执行中',completed:'已完成',terminated:'已终止'};
const sum={}; (data.rows||[]).forEach(r=>{const k=labels[r.status]||r.status||'未知'; sum[k]=(sum[k]||0)+(+r.amount||0);});
config.tooltip={trigger:'item'};
config.series=[{type:'pie',radius:'60%',data:Object.entries(sum).map(([n,v])=>({name:n,value:v}))}]; return config;

let inv=0,paid=0; (data.rows||[]).forEach(r=>{inv+=(+r.invoice_amount||0); paid+=(+r.paid_amount||0);});
config.xAxis={type:'category',data:['开票金额','已收金额','未收金额']}; config.yAxis={type:'value'};
config.series=[{type:'bar',name:'金额',data:[inv,paid,inv-paid],itemStyle:{color:'#fd7e14'}}]; return config;

const m={new:0,in_progress:1,waiting_customer:2,resolved:3,closed:4};
const c=[0,0,0,0,0]; (data.rows||[]).forEach(r=>{const i=m[r.status]; if(i!=null) c[i]++;});
config.xAxis={type:'category',data:['新建','处理中','待客户反馈','已解决','已关闭']}; config.yAxis={type:'value'};
config.series=[{type:'bar',name:'数量',data:c,itemStyle:{color:'#dc3545'}}]; return config;
